package com.vuelossanitarios.backend.api;
import com.vuelossanitarios.backend.api.dto.NotificationDtos.*;import com.vuelossanitarios.backend.security.CurrentUser;import com.vuelossanitarios.backend.service.NotificationService;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController {private final NotificationService service;public NotificationController(NotificationService s){service=s;}@GetMapping @PreAuthorize("hasAnyRole('DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public NotificationPage list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@AuthenticationPrincipal CurrentUser u){return service.list(u.id(),page,size);}@PostMapping("/{id}/read") @PreAuthorize("hasAnyRole('DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public void read(@PathVariable UUID id,@AuthenticationPrincipal CurrentUser u){service.read(id,u.id());}@PostMapping("/read-all") @PreAuthorize("hasAnyRole('DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public int readAll(@AuthenticationPrincipal CurrentUser u){return service.readAll(u.id());}}
